from fastapi import FastAPI, Header, HTTPException
from fastapi.testclient import TestClient
import pytest

app = FastAPI()

@app.get("/convert_true")
async def convert_true(x_token: str = Header(..., convert_underscores=True)):
    return {"x_token": x_token}

@app.get("/convert_false")
async def convert_false(x_token: str = Header(..., convert_underscores=False)):
    return {"x_token": x_token}

client = TestClient(app)

def test_convert_true_hyphen():
    response = client.get("/convert_true", headers={"X-Token": "foo"})
    assert response.status_code == 200
    assert response.json() == {"x_token": "foo"}

def test_convert_true_underscore():
    # This should fail if convert_underscores=True and we only accept hyphens
    response = client.get("/convert_true", headers={"X_Token": "foo"})
    assert response.status_code == 422

def test_convert_false_underscore():
    response = client.get("/convert_false", headers={"X_Token": "foo"})
    assert response.status_code == 200
    assert response.json() == {"x_token": "foo"}

def test_convert_false_hyphen():
    # If convert_underscores=False, we should not automatically convert X-Token to x_token
    response = client.get("/convert_false", headers={"X-Token": "foo"})
    assert response.status_code == 422

